//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::int::compare`; the
//! native twin is `benches/native/Bench/IntCompare.lean`.
//! Int words in the int32 range on both sides; every result stays there; operands in 16 values,
//! so equal ones are frequent

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::int;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(
            acc,
            match int::compare(
                &int_arg(int_box(((x >> 60) as i64) - 8)),
                &int_arg(int_box((((x >> 4) & 15) as i64) - 8)),
            ) {
                core::cmp::Ordering::Less => 0,
                core::cmp::Ordering::Equal => 1,
                core::cmp::Ordering::Greater => 2,
            },
        );
    }
    acc
}

fn main() {
    run(|| (), kernel)
}
